  const dotFix=document.createElement('style');dotFix.id='teaching-calendar-dot-fix';dotFix.textContent='.tc-schedule-legend>span{display:inline-flex;align-items:center;gap:4px;min-height:12px}.tc-schedule-legend i.tc-legend-dot{display:none!important}.tc-schedule-legend>span:nth-child(1)::before,.tc-schedule-legend>span:nth-child(2)::before{content:"";display:inline-block;width:7px;height:7px;flex:0 0 7px;border-radius:50%;box-sizing:border-box}.tc-schedule-legend>span:nth-child(1)::before{background:#36b6a7}.tc-schedule-legend>span:nth-child(2)::before{border:1px solid #b8ceca;background:#fff}.tc-schedule-kicker{display:none!important}.tc-schedule-toolbar>.tc-schedule-review-actions{display:flex;align-items:center;gap:8px;flex:0 0 auto}.tc-scheduled-card{cursor:grab}.tc-scheduled-card:active{cursor:grabbing}.tc-scheduled-card.is-dragging{opacity:.55}';document.head.appendChild(dotFix);
  let calendarAiOpen=false;
